def ctx(name,t,w):
    for m in re.finditer(re.escape(w),t): print(f'{name} [{w}]: ...{t[max(0,m.start()-80):m.end()+60]}...')
for w in ['14 August','9 September','March 20','November','16 December']: ctx('PLAN',P,w)
for w in ['August 13','March 20','May 20','August 20','October 1, 2026','September 16','Nov 25','Oct 24','updated']: ctx('GUIDE',G,w)
for w in ['March 20','August 20']: ctx('APPX_E',E,w)
ctx('APPX_A',A,'October 7')
EOF

