const ed=[...document.querySelectorAll('[contenteditable="true"]')].find(e=>/message body/i.test(e.getAttribute('aria-label')||''));
const lines=["Kenny,","","Attached is the draft Performance Technology Best Practices guide, built to the NCAA SSI Performance Technologies Recommendations (March 2026), along with the plan behind it.","","What is attached (7):","1. Plan (3 pages): what this asks of you and the timeline. Start here.","2. Guide, Draft v2 (10 pages).","3. Appendices A to E (2 pages each): Consent, Vendor Checklist, Offboarding Checklist, Annual Review, Tech Intake.","","What I need from you:","1. Agreement on the (3) decisions in the plan by 10/14. Happy to use our weekly check-in for this.","2. Items marked [Pending Kenny] are my recommendation. Mark any you would change.","","After that: input from OGC, Procurement, ITS and Athletic Medicine by 10/24, a full first draft to you by 11/6, and in use by 12/16. I will keep you updated as each office weighs in.","","Thanks,","Eric"];
const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
ed.innerHTML=lines.map(l=>'<div>'+(l?esc(l):'<br>')+'</div>').join('');
ed.dispatchEvent(new InputEvent('input',{bubbles:true}));
ed ? ed.innerText.slice(0,200) : 'no editor'

